# Proper analysis of 6-blocks
def analyze_6_blocks_in_row(grid_input, grid_output):
    """For a single row, analyze each 6-block and count how many stay 6"""
    w = len(grid_input[0])
    blocks = []
    start = None
    for c in range(w):
        if grid_input[c] == 6:
            if start is None:
                start = c
        elif start is not None:
            blen = c - start
            blocks.append((start, start + blen, blen))
            start = None
    if start is not None:
        blen = w - start
        blocks.append((start, start + blen, blen))

    if not blocks:
        return

    block_details = []
    for block_start, block_end, block_len in blocks:
        stayed_6 = sum(1 for c in range(block_start, block_end) 
                       if grid_input[c] == 6 and grid_output[c] == 6)
        result = [grid_output[c] for c in range(block_start, block_end)]
        block_details.append({
            'start': block_start,
            'end': block_end,
            'length': block_len,
            'stayed_6': stayed_6,
            'result': result
        })

    return block_details

# Analyze the entire grid
def analyze_grid(demo_input, demo_output):
    total_blocks = 0
    total_stayed_6 = 0
    total_stayed_6_by_len = {}

    for r in range(len(demo_input)):
        details = analyze_6_blocks_in_row(demo_input[r], demo_output[r])
        if not details:
            continue

        total_blocks += len(details)
        for bd in details:
            total_stayed_6 += bd['stayed_6']
            bd_len = bd['length']
            if bd_len not in total_stayed_6_by_len:
                total_stayed_6_by_len[bd_len] = 0
            total_stayed_6_by_len[bd_len] += bd['stayed_6']

    print(f"Total 6-blocks: {total_blocks}")
    print(f"Total stayed 6s: {total_stayed_6}")
    print(f"Average stayed per block: {total_stayed_6/total_blocks:.2f}")

    print("\nStayed 6s by block length:")
    for length in sorted(total_stayed_6_by_len.keys()):
        count = total_stayed_6_by_len[length]
        print(f"  Length {length}: avg {count} stayed (of {total_stayed_6_by_len.get(length, 0)}/count?)")

    # Now let's count blocks by length that ALL stayed 6
    print("\nAnalyzing each row's blocks:")
    for r in range(len(demo_input)):
        details = analyze_6_blocks_in_row(demo_input[r], demo_output[r])
        if not details:
            print(f"Row {r}: no 6-blocks")
            continue
        for bd in details:
            pct = bd['stayed_6'] / bd['length'] * 100
            print(f"Row {r}: block at col {bd['start']} (len {bd['length']}), {bd['stayed_6']}/{bd['length']} stayed 6 ({pct:.0f}%)")

        print()

analyze_grid(demo_input, demo_output)

# Let me check the vertical patterns - which columns have vertically connected 6-blocks
def find_vertical_6_blocks(demo_input):
    """Find columns with vertical 6-blocks of length >= 3"""
    h, w = len(demo_input), len(demo_input[0])
    vertical_blocks = {}
    for c in range(w):
        blocks = []
        start = None
        for r in range(h):
            if demo_input[r][c] == 6:
                if start is None:
                    start = r
            else:
                if start is not None:
                    blen = r - start
                    blocks.append((start, start + blen, blen))
                    start = None
        if start is not None:
            blen = h - start
            blocks.append((start, start + blen, blen))
        if blocks:
            vertical_blocks[c] = blocks
    return vertical_blocks

vert_blocks = find_vertical_6_blocks(demo_input)
print("Columns with vertical 6-blocks (length >= 3):")
for c, blocks in sorted(vert_blocks.items()):
    large = [b for b in blocks if b[2] >= 3]
    if large:
        print(f"  Col {c}: {large}")

def analyze_vertical_context(grid_in, grid_out):
    h, w = len(grid_in), len(grid_in[0])
    stay_data = []
    become_data = []

    for r in range(h):
        for c in range(w):
            if grid_in[r][c] == 6:
                up = grid_in[r-1][c] if r > 0 else -1
                down = grid_in[r+1][c] if r < h-1 else -1
                left = grid_in[r][c-1] if c > 0 else -1
                right = grid_in[r][c+1] if c < w-1 else -1

                stay = (grid_out[r][c] == 6)
                stay_data.append((r, c, up, down, left, right, stay))
                become_data.append((r, c, up, down, left, right))

    if not stay_data:
        print("No stay cases found!")
        return

    print("Stay analysis - first 20 cases where input=6, output=6:")
    for d in stay_data[:20]:
        r,c,up,down,left,right,stay = d
        print(f"  ({0},{c}): up={up}, down={down}, left={left}, right={right}, stayed={stay}")

    print("\nFirst row analysis:")
    first_row = []
    for d in stay_data:
        if d[0] == 0:
            first_row.append(d)
    for d in first_row:
        r,c,up,down,left,right,stay = d
        print(f"  ({0},{c}): up=-1, down={down}, left={left}, right={right}, stayed={stay}")

analyze_vertical_context(demo_input, demo_output)

